) AS (
  VALUES 
    (518::BIGINT, 'Vaya preparado a la clase porque lo que hace principalmente es hacer ejercicios pero es un excelente profe y buena persona trata de ayudar bastante y califica suave'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-13T00:00:00+00:00'::TIMESTAMPTZ, '7b318765fb981fbf22aeaf487e42ceb217b94d69cefd02ed2a17e53344b963dd'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Ponga mucha atención, le recomiendo llevar usted la materia al día porque en clase casi que solo problemas y estaría un toque perdido'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2025-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'bfcfd84df74e484cafef42ffea3231b86cea970abdfe98361e560898041170af'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Este señor da explicaciones muy confusas y se le entiende muy poco lo que escribe en la pizarra. No lo recomiendo si es la primera vez que lleva el curso (a menos que usted sea bueno en mate).'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-26T00:00:00+00:00'::TIMESTAMPTZ, 'd3d9eb39dde8f292177b3a50d1dace93a64c3e2c6c00e9101ef6cf8d0268e925'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'El curso fue muy compacto por la misma modalidad, ayuda mucho si usted participa en clases y la pulsea. Es muy directo con lo que dice, explica de manera arcaíca muchas cosas pero estudiando las guías de la cátedra le va bien. No falte a clases y participe, pregunte y demuestre que tiene interés.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'b09cf52f7cd8f09a5560345fb53bcbed5479401a1682160e3f730220c2ab0921'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'El profe es muy pura vida, califica muy suave y hace que las clases sean lo menos aburridas posibles. Estudie las guías de la cátedra y con eso lo hace todo super bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-23T00:00:00+00:00'::TIMESTAMPTZ, '032605bac3c4792531725b6b16f65c12484f617e30e386fc7195ec2a29416ffb'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Es un profesor decente para llevar el curso. El profesor califica suave, lo cual se agradece. Para explicar puede ser algo desordenado pero si usted va preguntando el está dispuesto a explicar nuevamente. Se le olvidan las cosas entonces hay que recordarle a veces por notas o exámenes.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, '63623721b679d02eaff44db1e23d07d240304415e51e0431bf84fa0c48dc4d58'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'Buena nota el profe, a veces se le cuesta entender lo que esta explicando pero los quices que hace no son tan dificiles, ademas de que si participaste bastante y fuiste a todas o mayoria de clases prestando atencion te da puntos extra.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'f48d68ab961457f41b3991f832cddf006eee83e375b3cbf3d51e8a1ec154c31c'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'Se distrae y enreda mucho en las clases. Solo se pasa si usted va a horas de tutoría. Mejor ni vaya a clase si tiene sueño o va a usar el cel, porque lo va a pasar molestando toda la clase. "Los estudiantes universitarios se alimentan de fotosíntesis, no duermen ni comen, es así de simple" M. Marín'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'cd3d5aeea24ebb3a8d48b4b25d5eec206d2b6ef08c9857c61c0f20ee65501a3a'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'No explica bien los conceptos y es desordenado.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-03-16T00:00:00+00:00'::TIMESTAMPTZ, '312438226a68de0ced3394c7cd54e2c3e9c871a0a23ad84e9c836c39b5d271ce'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'El profe no sabe enseñar, se enreda bastante y pretende que uno sepa la materia a la primera. Califica suave'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'dcbc1f20664ba9873f2c9e6f4aa560d3a5081049a8165cd520f2deb4a0f28b51'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Es malísimo, ofrece muchos puntos extra y no los da nunca. Sube las cosas siempre tarde o no las sube nunca. NO MATRICULEN CON ESTE'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, '9dd6a28a38223ca790d21e46db66c71b88ca0e89aba786c96af8543a9b8eaea5'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'Tenia como 30 años sin dar el curso y se evidencia bastante. No prepara las clases y solo llega a explicar lo que la catedra dice que se debe de cubrir esa semana, lo único bueno es que responde muy bien a las dudas'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-07-30T00:00:00+00:00'::TIMESTAMPTZ, '2991ae7b6c5363a7913cd3cef60d382e1a6238a3cb2f7770e55be83ecb144100'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'Bastante meh, se enreda explicando a veces pero no califica duro, yo pasé estudiando las guías de catedra porque la clase no se me hacia muy interesante.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3bc87e47791fa7546bee5e6e18a817f742e1c4ddace0213e51ae5ef6e5d6b7e3'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'El profe es una teja, se pasa bien en clases solo que se enreda un poco, si ve que uno lo intenta al menos, él ayuda mucho, estudien con la cátedra y pasan porque califica muy suave.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Pocos exámenes']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e3e3349f1b7f521c8530d2b769815b1c3c24b3d636af014bf13f7e6ad9513d30'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'Simplemente, con el mae se pasa, con tal de que ud le hable bastante. No hizo quices cuando lo llevé, y ayuda demasiado a la gente. Toda la clase es el bro haciendo ejercicios, casi 0 teoría así que traiga dudas. Se pasa vacilando en clase y a veces se le escapan evaluaciones, pero se habla con el.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '6225a8f9490feb2e331f420edececf259974045146266c738c56480e64da2ccc'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'El curso por si solo es lo que lo vuelve complicado, pero considero que el profe hace lo posible para que uno entienda y si ve que uno se esfuerza le brinda incluso ayuda extra, a la hora de calificar los exámenes es bastante flexible, en ocasiones se enreda dando la materia pero lo corrije'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b28ee594d981f76dcaf82e95a8249559299ea34d873a5b95aa59add14c81ffbd'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'La peor opción para llevar proba, el curso en si ya es difícil y confuso pero él logra hacerlo aun peor. No llevar ningún orden en sus clases, por lo que se termina teniendo una mezcla de temas diferentes cada día. Al final intenta ayuda si vio que durante el semestre hubo interés y esfuerzo'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c5a6f572362a8d5a5e71dbf7ce9cd9d435780d7d0dccddc75d1e00905661c00b'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Excelente profe! La asistencia no es obligatoria pero él se acuerda de todos los que van a clase y ayuda a esas personas lo más que puede. En realidad en la clase a veces confunde pero mientras usted vaya al día con la materia y vea las consignas semanales todo bien. Matrícule con él sin miedo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '77731753bf396c57cba258c5199d279c66093d4a65d98074fb4e5d5cec2e40f1'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'Es un curso pesado, aveces se enreda al explicar pero ayuda mucho si ve que uno le pone, no califica tan duro y es muy pura vida'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Pocos exámenes']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '62ff14499aa527bb8b0448d4e402babb5d1c0fbb6926ce08925e843cd022cb46'::TEXT, ARRAY[1018]::BIGINT[]),
    (518::BIGINT, 'Llevé el curso tanto virtual como presencial y en virtual lo feo es que casi nadie participa pero si puede estudiar usted solo dele sin miedo, en presencial lo imporante es poner mucha atención y llegar hasta el final, el profe ayuda si usted le pregunta, el curso por si solo es duro.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-13T00:00:00+00:00'::TIMESTAMPTZ, '82c07677e495ce3bcdb535edfd0d5ed3cbc8dd40af57682262755a7cd46b29a8'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Si tiene otra opción, aprovéchela. Es mal profe, tiene pasión, si usted le pregunta el mae hace lo posible para que usted entienda pero no explica muy bien, es muy desordenado, adora humillar y tratar mal, es un desmadre con trabajos y notas. Mi clase inicial era de 40 personas aprox, terminó de 8.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-19T00:00:00+00:00'::TIMESTAMPTZ, '221a10eb006b9563faebaa8660bd3688945ddf41a327ed49549462c162b591f4'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'En virtuales la clase es pesada. Sin embargo, tuve la oportunidad de ir a sus clases presenciales regularmente y es muy pura vida. Califica suave; cuesta que responda por Telegram, pero por correo bien. No deje el curso, nunca se pierde con él aunque vaya mal y no falte a clases, eso suma con él.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, '5ef58545afd55749bfb2cfb94fe02bed32e79f57cb2ffe35df90c39c906a841e'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Este profe es una basura, no hay otra palabra, debería estar pensionado ya, se le olvida/ignora todo lo relacionado con la cátedra, hasta da vergüenza que sea el coordinador.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '1d87390f32bf6788fc1abbded21e9e85d34cc4cc6df9556e8587ba5064c4fbc0'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'El profesor es bueno explicando, la materia demanda de parte del estudiante para pasarla pero el profe siempre está dispuesto a ayudar lo más posible, a veces se confunde con los números de los ejemplos que da pero si uno pone atención no hay razón para no entender'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-24T00:00:00+00:00'::TIMESTAMPTZ, '9233136b62ca635eab1df02115758b5fd5b1ae56a9f75449e854f3b543c2292b'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Tiende a tratar mal a los estudiantes, y a la hora de explicar, lo trata a uno como si ya supiera todo lo que el sabe y en muchas ocasiones va super rápido'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, '5b765e886a07770078c487670971788763ea9dec5df02fababc481db039eb0df'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'No vale la pena llevar un curso con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'dd86b79237da1620156aad85db91f126bd142dfc7068125b014957a263183437'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'El profe no es del todo malo pero no hay mucho interés en las clases por parte de los estudiantes y del profesor, el curso se puede pasar viendo los videos y haciendo un sacrificio a los dioses.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ac3b75ff17dd423ce654ca96b319bb69a382ce855526e5254db1b663c65618d1'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Malo, no sabe explicar. No le gusta enseñar. Le falta el respeto a los estudiantes. No debería ni siquiera ser coordinador de una materia.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5ddd5b4ec150d64ea77399e8e7aea54975d5e1e0a15a43efca9bc78c8bc6d297'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Las clases son una pérdida de tiempo, no se le entiende nada la letra, trata mal al estudiante, los problemas que plantea siempre tiene problemas de ambigüedad y espera que uno los resuelva justo como él se los imagina'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'cc14762a0ff7d17b27d698b8d231f516be299e85f7e4efd26d58906ad680a31e'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Todo el curso fue una falta de respeto con los estudiantes al punto que nadie se conectaba a modo de protesta. Desde ignorar los mensajes de telegram hasta insultar a los estudiantes en clases. 0 Vocación y mucho menos capacidad de enseñar'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'aba07aae6da91c0eb77c4b0ead1b2ee6ae8a095300ca5bf94d5c4bce23005a0e'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Falta de respeto con los estudiantes, literalmente es una basura de profesor. No explica, nunca responde mensajes. No bote el semestre y no meta con el mae. Es como una vaca en un techo uno no tiene ni la menor idea como llego ahi. Legitimamente el peor profesor del TEC'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '3d1edd8e8f7ba8c9704143aa9b66fe5be1ddb69c07325a3c5de7caa859f4f2f8'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Malísimo, no se le entiende la letra, ni lo que dice. Revisa como le da la gana y trata a los estudiantes como basura.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '056ff8ae88920a634d29d2b0d324b9dfec2715e3d9c3b699cc31cbce6997773e'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'el trato con el estudiante es poco grato'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '3ada6860eaf7f678e5cf06a2318d57d2f4c8f410e9955dc4bcef6f74803af96e'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'La verdad no vale la pena llevar un curso, no se embarque. Son de esos profes que se quedan el 90% del grupo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'fbea9840a8374611076077a1c550e28dcbca2a630f1400f3e3e4fb284bbc63c0'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-16T00:00:00+00:00'::TIMESTAMPTZ, '6c19e87bfd3325f1b20325a99ff44d5f60ea5dee11890749a2bd4eedf995bf37'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Peor profe para Proba'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-04-29T00:00:00+00:00'::TIMESTAMPTZ, '8ff383bfd36c3fd5480312a561a75a27047eedaaa12ff93c8b7e6b0443868faf'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-04-27T00:00:00+00:00'::TIMESTAMPTZ, 'fd977846d96dae7b47a18f517c14b9297c8941ecf0f4d17cde117665d07168ef'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Uno le escribe para dudas y ni responde, dura un montón para entregar calificaciones, en mi caso era semana 10 y si sabía que llevaba de notas en nada de lo que se había realizado'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Deja trabajos largos']::TEXT[], '2022-04-08T00:00:00+00:00'::TIMESTAMPTZ, '1dbc9ecbe964b300bdf3b07910b51f17abb01bea8b4dcc89912e7cd5de726767'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'El profe es muy bueno, no es el mejor explicando pero es buena nota en general, siempre esta dispuesto a ayudar y si uno ocupa ayuda por pv lo ayuda, es desordenado si bastante da todo al final pero los ejercicios que hace en clase es tal cual el examen'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-08T00:00:00+00:00'::TIMESTAMPTZ, 'f2f19d369541afa4a4b916b7155c4aa8943d4927745a1599dc398e6649779d7d'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Para probabilidad es un profesor decente, si bien sus apuntes son enredados se puede llevar bien el hilo de la clase si estudia algo mínimo, sus ejemplos son los mismos que en el examen (virtual). Si lleva la materia al día puede pasar el curso sin problemas, es carismático y brinda ayudas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '5fd10aacefe6ad9baa60c3d8967beb9b8ce2834c4e468903113d2a5dcd60bd98'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, '(virtual) Nadie se presenta a las clases, da las clases muy enredadas y no se le entiende bien. Califica todo hasta el final, muy desordenado con las tareas y con las notas del curso.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-10T00:00:00+00:00'::TIMESTAMPTZ, '78511648ef1d3d6cd6916269ed37e51b3475c3f3a358e10865b9503327098f88'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Clases inútiles, en semana 10 más de la mitad dejamos de asistir porque eran una perdida de tiempo, según sé solo como 6 compañeros seguían yendo (a qué no sé). A todo eso sumele que en semana 18 y con el examen final realizado no sabemos nada de las notas. Un irresponsable de primera.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9841c84251194ae918da3226a63acbc044c34fff6e3abba30eb823bc01ccf801'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Semana 16 y este señor no ha dado ni una sola nota, no sube los vídeos de las clases, nunca responde una duda fuera del horario de clases, nunca sabe cómo vamos, tiene un desorden con las tareas, unas por correo otras por TEC digital o Telegram. Que horror'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas']::TEXT[], '2021-06-10T00:00:00+00:00'::TIMESTAMPTZ, '6fd448432e149ccd4d1c070ff561fe28d6c183820283f6e8de956e5553478fb3'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'No entiendo cómo alguien tan irresponsable es profesor. Nunca habla claro, siempre hay que andar detrás preguntándole por fechas o asignaciones, nunca da un feedback, hoy dice algo mañana se contradice.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-04-07T00:00:00+00:00'::TIMESTAMPTZ, 'cc13d7000320cbe238a45bc1c2e66d2d550d83c75c98b7e0a422b3c2a74b1b86'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Realmente, ayuda tanto como pueda, si tienes dudas con gusto te las aclara, improvisa un poco si pero lo hace bien, tiene paciencia y el ambiente en general es muy amigable. Intenta la clase anterior al examen repasar todos los temas que entran. Lo recomiendo. Lo malo, da las notas hasta el final.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-03-05T00:00:00+00:00'::TIMESTAMPTZ, 'c0496502c500d8feff714b218b981d972f9cd4bd6347743f23c36e1bc1d16690'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Bueno: Él ayuda mucho y te explica cuanto sea necesario, no importa si se devuelve. Deja tareas pequeñas como puntos extras, ayuda mucho si le va mal en el examen. Malo: Es muy desordenado con la notas, las entrega hasta el final. Guarde todas las evaluaciones.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'ca691d82efb15cbacd7413759483e49250a5ef401aa09bf98be089bf06510043'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'no da las notas conforme transcurre el semestre, todo hasta el final. Malo explicando no lo recomiendo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '02f37af883a9101c0e12d36d4e179425efcbae74160110c3c3ea2c8acb0ead52'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Sumamente desordenado, no entrega notas conforme avanza el semestre y explica muy mal, se enreda solo con los ejercicios'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, '07413d122682123099f5a8666c98ea9cf439839ccfcf497a524a8f807d5b234c'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Creo que probabilidades es su curso favorito y por eso lo da tan bien, es un poco desordenado con las evaluaciones pero siempre está dispuesto a ayudar y explicar cuantas veces sea necesario. Con mi grupo se llevó super bien y creo que la mayoría disfrutamos llevar el curso y aprendimos bastante.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-20T00:00:00+00:00'::TIMESTAMPTZ, '93fc443b7b2f440cc68c0944b3691cfb4c3fbd5539402893b30b71ebec2f2da4'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Malo. No es nada organizado, no le interesaba preparar las lecciones y cero respeto hacia los estudiantes. Si lo puede evitar, hágalo.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas']::TEXT[], '2020-12-09T00:00:00+00:00'::TIMESTAMPTZ, '02d1d124885e188be406d67cb2958d87b8f66a74923954ae8ec41fc33cd2edcc'::TEXT, ARRAY[4847]::BIGINT[]),
    (518::BIGINT, 'No se los recomiendo. La metodología es mala, no dio las clases, solo nos pone a exponer. Cuando uno comenta en clase dice que está mal y hace comentarios despectivos.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2020-09-09T00:00:00+00:00'::TIMESTAMPTZ, '44557c07918537c160ed1ea28e35367fc299b340dc69b5abb9c301eef60bf493'::TEXT, ARRAY[4847]::BIGINT[]),
    (518::BIGINT, 'Es el peor profesor que he tenido, no se le entiende nada. En el primer examen toda la clase salió mal, le pedimos que resolviera el examen en clases y ni él supo hacer los ejercicios.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-05T00:00:00+00:00'::TIMESTAMPTZ, '7cf83af92e4733a5c6efbdc0f0202a7022b9b5e8425089931e245e72dba51b22'::TEXT, ARRAY[1632]::BIGINT[]),
    (518::BIGINT, 'tiene una manera peculiar de explicar, pero ayuda mucho para que pasen, obliga a pensar los ejercicios'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'b3bd8b7315d88e93930858d185b031f3c9907ad6d74832e992f80c9321d7e3a2'::TEXT, ARRAY[1670, 1669]::BIGINT[]),
    (518::BIGINT, 'Excelente profesor, lo recomiendo. Da ejemplos muy claros e interesantes de proba, da gusto sus lecciones.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-13T00:00:00+00:00'::TIMESTAMPTZ, '6aacdebc9429a53a610a8e67265b38dc2e99c0c5e8b4d4edbdb6f3242c04a2ad'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Excelente profe, las clases son un poco desorganizadas pero a la hora del examen es súper fácil pasar con los ejemplos que da en clase que tienen una mayor dificultad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2019-01-23T00:00:00+00:00'::TIMESTAMPTZ, '8d38728554f234c53c2245c76fac8f4ddbaa34139b49f5c926fe7433f6f53003'::TEXT, ARRAY[935]::BIGINT[]),
    (518::BIGINT, 'Poca gente en clases, como persona es un poco grosero aveces, como profesor intenta que sus estudiantes aprendan realmente(lo ideal) y no solo para el examen.Califica suave Consejo: tenga la materia al día porque hace preguntas en clase y saque lo mejor en quices semi-virtuales porque al final salva'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '0aed6fb37a6e4c7744c11c42fdc3f7dcdc4cf54f5eaefac7feed235f67763629'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Yo le entendia todo lo que explicaba.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-18T00:00:00+00:00'::TIMESTAMPTZ, 'f497b0f34b5e9d045ec35c282bc913b0da09ebc5cb20c85f61e7756508da3c22'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Pésimo pedante se cree superior pero no sabe explicar nunca más con él'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '0e8eb19e4b5f013ddbc5d9f68c0c35f3a979a4b9ed113de649bde730a0d729f4'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'El no es tan malo como los comentarios dicen, se empeña en explicar de manera que el estudiante entienda aunque no siempre sea de la manera mas clara, que no le pregunten es otra cosa, siempre esta disponible para consultas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '1dc748b7dd69bad18565903e3f6dd69dced949bb03d403bf42af0f02644bbb40'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Me parece que sabe mucho de los temas, pero su capacidad para enseñar es nula. A la hora de hablar es muy directo por lo que muchos compañeros se sentían ofendidos cuando le preguntaban algo y él solo les decía que estaban mamando.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'f2c52d8fceca08ea6d1782c3156c48f1bd52b92d5819f6a4dcf662c29bf66956'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Para mí es un buen profesor, aunque a algunos no les guste como enseña. Es muy comprensivo y ayuda a los que saben comportarse. Él sabe bastante. Todavía no acaba el semestre.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-10-27T00:00:00+00:00'::TIMESTAMPTZ, '9197fc99050cb3124add22aa025e5d0b69476bd1e3b897fbed5ae389199e9e25'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'No se le entiende un carajo, corrige de manera no muy amistosa. Responsable de proba semi-virtual, parece que los videos los graba añejo y en el baño.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2017-10-27T00:00:00+00:00'::TIMESTAMPTZ, '7708e5fc9457cd366401813c434994a4d2ac7258634ff1eb378a7c6aeb0b3468'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'El peor profe con el que he recibido clases. Haga todo lo posible por evitarlo'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '36dd7006dd768eb19abc8a8e781e6e2dba22edfedf9c0a30e89ddfb14746539c'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Pésimo profesor, podrá saber mucho, pero no sabe explicar, los ejercicios que hace en clases ni el mismo sabe como resolverlos y los deja a medio palo. Una pérdida de tiempo ir a clases yo iba solo porque es un 10%'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b8f313b30c85896f53a87dfcbd25da1709ac897bfa64c834f1d2025fb38a3f66'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'con este sistema semi-virtual es un pésimo profesor. Ejemplos se los inventa en clase y por lo general no los termina. letra inentendible, no explica nada bien. Exámenes de la escuela son duros, tareas igual. Clases muy aburridas'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Exámenes retadores']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '9a1751e2afdc0e691b1dfb578622f561483c6b0342af7a13640ef431a70a6ae8'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'Buen Profe pero si hay algunas cosas que no deja claras qué hay que leerlas de los folletos'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a044521ac1d0bd137a0468ed15b3c86376f7de0edc75c72afb350fc7d071a9da'::TEXT, ARRAY[935]::BIGINT[]),
    (518::BIGINT, 'A pesar de dar las clases desorganizado no explica tan mal, se preocupa mucho porque el estudiante comprenda la materia bien. En consulta es muchísimo mejor que en clase.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '304e2fc70c313f30d513367bdb91c30a5d1c382f898921145954d81493035042'::TEXT, ARRAY[935]::BIGINT[]),
    (518::BIGINT, 'es muuuy desordenado, no se le entiende nada. pésimo profesor laverdad'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '37c86be69aa55af1bd145f886da1edc5139f411ce2a9f43b77ed8c5bb1bf002e'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Muy malo, por dicha pase el curso pero no lo recomiendo para nada! Desordenado, nunca esta en la oficina.Malisimo!!'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-01T00:00:00+00:00'::TIMESTAMPTZ, '3e9781c3e638b5504fe04682fdcb57bf9287cbfeb40a9f91812fe1b4823081b4'::TEXT, ARRAY[563]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-25T00:00:00+00:00'::TIMESTAMPTZ, '5d2df62d8cad85beb1bfef21aadcb8af76e881e721d543cc3025d99429ad9943'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4c639a7c9914f905867fa9ef0fcf71045c0b851db529511e04bbff1d9d20fee7'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Si hay otro matricule con el otro!!!!!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'baa908dda4b00e2e6772c7ffffd6d2c637c010ec824dd0578aa77082f507b8a9'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '6d6f4d898f528a3d4257c4d980cca8a1ccdef098f5d4526172b88b55207e5f60'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Es desordenado, si matricula con él, descargue el folleto que usan otros profes para que se refuerce con eso, puesto que sus ejercicios son improvisados. Hace siempre prácticas antes de los exámenes y CUALQUIER ejercicio que le lleve él lo resuelve,'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-26T00:00:00+00:00'::TIMESTAMPTZ, 'b5b96b6f2303ee41d266a2c1308085fa3f5f60c7c3167cc301270cd5fa7a9fd2'::TEXT, ARRAY[634]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-05T00:00:00+00:00'::TIMESTAMPTZ, '99de489448638dfc5843fcdbaf0c4c018c0bfd9a73a209931aacea000b5f85cd'::TEXT, ARRAY[634]::BIGINT[]),
    (518::BIGINT, 'no explica lo que debería y se inventa los problemas que por lo general no resuelve bien, no se le entiende la letra y no se guía con los folletos de la escuela'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-03T00:00:00+00:00'::TIMESTAMPTZ, '311bb9fab13fdcb186b6379d69b241f8f34e56a01d0780d11fff355e0e781371'::TEXT, ARRAY[935]::BIGINT[]),
    (518::BIGINT, 'En Proba es un buen profe, es lo que le gusta. las clases son amenas. Sí hay que ponerle bastante. En la medida de lo posible prefiere no usar libro. Explica bien, hay q estar concentrado. Ayuda mucho a los estudientes par que pasen. Yo lo recomiendo, especielmente para verano :)'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'c58ac8b3b8989a69613316ecb760338cf7664ed65e99f93a79b07af8499084a3'::TEXT, ARRAY[1049]::BIGINT[]),
    (518::BIGINT, 'No sabe dar clases, cuesta mucho entenderle. Nunca responde a los correos y casi nunca (por no decir nunca) está en la oficina. x el otro lado califica suave y las clases son entretenidas. Nota: Nunca le entendí nada -> me quedé... Pero lo llevé en verano con un mejor profe y ahora soy un crack!'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-22T00:00:00+00:00'::TIMESTAMPTZ, '0e09a570d5bc7936ec023e70a31827a489333e3aab4532f918f616cc9d3068e3'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Explica rápido, pero sabe demasiado y le explica todas las veces que usted necesite. La clase es bastante entretenida, califica justo y es bastante buena nota.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, '2516ffa3e98c780d82d852e18bf1d0c9b0401ef80eb34d1b02cff019de09abf9'::TEXT, ARRAY[1034]::BIGINT[]),
    (518::BIGINT, 'va rapido con la materia hay que repasar si no uno llega a la clase perdido no hace muchos quices pero cuando hace son rudos califica suave los examenes y los ejemplos que da son rudos yde todos los tipos posibles solo que hay que repasarlos para entenderlos'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'c611f0731451d6193e187c5ef3fc64868bd1a9036bbdb14527edd809a713d5f9'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '7f19ea66108eb3bf67559b7e4b4d9be5fedece5bf3a5ae62661bcf57b43a212d'::TEXT, ARRAY[1034]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-30T00:00:00+00:00'::TIMESTAMPTZ, '957cae515bd7123d6f8e84d4922fbac6f0c9420bc8a8a8e5b9cec45c78e2a769'::TEXT, ARRAY[634]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'a18b73ebc4132668d00b8ba5d3e928b062c02bf1d92b601ac602671d618afa7c'::TEXT, ARRAY[935]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-25T00:00:00+00:00'::TIMESTAMPTZ, '1d11bfde51cd3d17cfe54438c1a619309d469b9a6564ca666d3c7b9e3415b6dd'::TEXT, ARRAY[634]::BIGINT[]),
    (518::BIGINT, 'Es muy desordenado no explica nada bien'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '88f51301548d9002368e84a519cc39c1a86051dd371830ce6778201cbe8920ef'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Explica MUY rápido (uno solo puede: copiar en el cuaderno ó ponerle atención). Le tapa a todos los del lado izquierdo de la clase. Los quices son MUY rudos. Lo explica todo muy complicado y se cree la mamá de Tarzán porque estudió matemática pura.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'bc156e32429196166119e35dce02fd5f45829b51cea00c0be2ae47d350ef03f0'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Malísimo, no explica bien, es desordenado, pero califica suave, si meten con él vayan a otras clases y solo lleguen a hacer quices, hace quices rudísimos.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '3a0d1cda68b2124a269b239ac5b50d6f1f12639011d6843bf0e621f32e5d9178'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'No es mal profe pero explica muy rápido y es bastante desordenado (muchas veces no se sabe el tema que se está viendo). Si se está con él hay que buscar otros medios de ayuda porque si no es difícil...Lo bueno es que revisa bastante fácil. No lo recomiendo para cursos complicados.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'b445de7a4004eac98eece4b4ad53e1607d36263deeb44eda3b086d02627b3ce6'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Muy bueno explicando... Revisa muy relajado... Ayuda bastante...'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'b5f0d24d476c70cfd72bf1994ea34f4b18f246fc843d49c2b570331ae181c695'::TEXT, ARRAY[605]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'b85232c8ae026ac335bc2aaacb8e5e2f836a05f4e9a6e507371f1c218b4b320e'::TEXT, ARRAY[1670, 1669]::BIGINT[]),
    (518::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '89467b2d40f9d2b10e1cdee0d8e38e1287f2efffef96d5af305d01c5dec8286a'::TEXT, ARRAY[634]::BIGINT[]),
    (518::BIGINT, 'DEMASIADO MAL PROFE!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'e307e2effc8bded40384b0b9de925d67dd2bdf88caad800d3ffa5d4549b7aa62'::TEXT, ARRAY[1034]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
